export async function createScene(engine, canvas, BABYLON) {
  console.clear();
  const scene = new BABYLON.Scene(engine);
  scene.clearColor = BABYLON.Color4.FromHexString("#8B3939FF");
  scene.useRightHandedSystem = true;

  var camera = new BABYLON.ArcRotateCamera("camera", BABYLON.Tools.ToRadians(90), BABYLON.Tools.ToRadians(65), 10, BABYLON.Vector3.Zero(), scene);
  camera.setTarget(new BABYLON.Vector3(0.07, 1.14, 0.06));
  camera.alpha = 1.628;
  camera.beta = 1.4;
  camera.radius = 1.6;
  camera.inertia = 0.4;
  camera.wheelDeltaPercentage = 0.3;
  camera.panningSensibility = 10000;
  camera.minZ = 0.01;
  camera.maxZ = 10000;
  camera.attachControl(canvas, true);

  var hemiLight = new BABYLON.HemisphericLight("light", new BABYLON.Vector3(-0.18, 0.29, 0.93), scene);
  let hemiIntensity = 5;
  hemiLight.intensity = hemiIntensity;

  var dirLight = new BABYLON.DirectionalLight("DirLight", new BABYLON.Vector3(0.17, -0.35, -0.91), scene);
  dirLight.position = new BABYLON.Vector3(1, 1, 0.5);

  let rootMesh;
  let originalMaterial, shaderMaterial;
  let isPBR = true;

  BABYLON.SceneLoader.ImportMeshAsync("", "https://raw.githubusercontent.com/UN1TOne/3DAsset/master/", "human_heart.glb").then((result) => {
    rootMesh = result.meshes[0];
    rootMesh.normalizeToUnitCube(true);

    const heartMesh = rootMesh.getChildMeshes(false)[0];
    originalMaterial = heartMesh.material;

    camera.setTarget(heartMesh);
    camera.alpha = 1.628;
    camera.beta = 1.4;
    camera.radius = 1.6;

    BABYLON.Effect.ShadersStore["customPBRVertexShader"] = `
          precision highp float;

          attribute vec3 position;
          attribute vec3 normal;
          attribute vec2 uv;

          uniform mat4 worldViewProjection;
          uniform mat4 world;
          uniform float time;

          varying vec3 vPosition;
          varying vec3 vNormal;
          varying vec2 vUV;

          void main() {
              float pulse = sin(time * 3.0) * 0.05;
              vec3 newPosition = position + normal * pulse;

              gl_Position = worldViewProjection * vec4(newPosition, 1.0);
              vPosition = vec3(world * vec4(position, 1.0));
              vNormal = normalize(vec3(world * vec4(normal, 0.0)));
              vUV = uv;
          }
      `;

    BABYLON.Effect.ShadersStore["customPBRFragmentShader"] = `
      precision highp float;

      varying vec3 vPosition;
      varying vec3 vNormal;
      varying vec2 vUV;

      uniform vec3 lightPosition;
      uniform vec3 lightDirection;
      uniform vec3 hemiDirection; 
      uniform float hemiIntensity;
      uniform vec3 cameraPosition;
      uniform sampler2D albedoTexture;
      uniform sampler2D metallicRoughnessTexture;
      uniform sampler2D bumpTexture;
      uniform float metallic;
      uniform float roughness;

      const float PI = 3.14159265359;

      // Normal Distribution Function (Trowbridge-Reitz GGX)
      float D_GGX(float NoH, float roughness) {
          float a = roughness * roughness;
          float a2 = a * a;
          float NoH2 = NoH * NoH;
          float denom = NoH2 * (a2 - 1.0) + 1.0;
          return a2 / (PI * denom * denom);
      }

      // Geometry Function (Schlick-GGX)
      float G_SchlickGGX(float NoV, float roughness) {
          float r = roughness + 1.0;
          float k = (r * r) / 8.0;
          return NoV / (NoV * (1.0 - k) + k);
      }

      // Fresnel (Schlick 근사)
      vec3 F_Schlick(float VoH, vec3 F0) {
          return F0 + (1.0 - F0) * pow(1.0 - VoH, 5.0);
      }

      // Bump 매핑으로 법선 계산
      vec3 perturbNormal(vec3 normal, vec3 bump, vec2 uv) {
          vec3 tangentNormal = bump * 2.0 - 1.0;
          vec3 dPx = dFdx(vPosition);
          vec3 dPy = dFdy(vPosition);
          vec2 dUVx = dFdx(uv);
          vec2 dUVy = dFdy(uv);

          vec3 T = normalize(dPx * dUVy.t - dPy * dUVx.t);
          vec3 B = normalize(cross(normal, T));
          mat3 TBN = mat3(T, B, normal);

          return normalize(TBN * tangentNormal);
      }

      void main() {
          // 텍스처 샘플링
          vec3 albedo = texture2D(albedoTexture, vUV).rgb;
          vec3 metallicRoughness = texture2D(metallicRoughnessTexture, vUV).rgb;
          vec3 bump = texture2D(bumpTexture, vUV).rgb;

          // 텍스처 값과 유니폼 값을 조합
          float texMetallic = metallicRoughness.b;
          float texRoughness = metallicRoughness.g;
          float finalMetallic = (metallic < 0.0) ? texMetallic : metallic;
          float finalRoughness = (roughness < 0.0) ? texRoughness : roughness;

          // Bump 매핑으로 법선 조정
          vec3 N = perturbNormal(normalize(vNormal), bump, vUV);
          vec3 V = normalize(cameraPosition - vPosition);

          // 1. 점 광원 또는 방향성 광원 계산
          vec3 L;
          float NoL;
          if (length(lightDirection) > 0.0) {
              L = normalize(-lightDirection); // 방향성 광원
              NoL = max(dot(N, L), 0.0);
          } else {
              L = normalize(lightPosition - vPosition); // 점 광원
              NoL = max(dot(N, L), 0.0);
          }

          vec3 H = normalize(V + L);
          float NoV = max(dot(N, V), 0.0);
          float NoH = max(dot(N, H), 0.0);
          float VoH = max(dot(V, H), 0.0);

          // F0 계산
          vec3 F0 = mix(vec3(0.04), albedo, finalMetallic);

          // Cook-Torrance BRDF (Specular)
          float NDF = D_GGX(NoH, finalRoughness);
          float G = G_SchlickGGX(NoV, finalRoughness) * G_SchlickGGX(NoL, finalRoughness);
          vec3 F = F_Schlick(VoH, F0);
          vec3 specular = (NDF * G * F) / (4.0 * NoV * NoL + 0.001);

          // Diffuse (기존 광원)
          vec3 kS = F;
          vec3 kD = vec3(1.0) - kS;
          kD *= 1.0 - finalMetallic;
          vec3 diffuse = kD * albedo / PI;

          // 2. HemisphericLight 계산
          vec3 hemiL = normalize(hemiDirection);
          float hemiNoL = max(dot(N, hemiL), 0.0); // 반구광 방향과 법선의 각도
          vec3 hemiColor = vec3(1.0) * hemiIntensity; // 세기를 반영한 반구광 색상
          vec3 hemiDiffuse = kD * albedo / PI * hemiNoL * hemiIntensity; // 반구광 기여도

          // 최종 색상 합산
          vec3 lightColor = vec3(1.0); // 기본 광원 색상
          vec3 radiance = lightColor * NoL; // 점/방향성 광원의 radiance
          vec3 color = (diffuse + specular) * radiance + hemiDiffuse; // 반구광 추가

          // 감마 보정
          color = pow(color, vec3(1.0 / 2.2));

          gl_FragColor = vec4(color, 1.0);
      }
    `;

    shaderMaterial = new BABYLON.ShaderMaterial(
      "pbrShader",
      scene,
      {
        vertex: "customPBR",
        fragment: "customPBR",
      },
      {
        attributes: ["position", "normal", "uv"],
        uniforms: [
          "worldViewProjection",
          "world",
          "view",
          "projection",
          "lightPosition",
          "lightDirection",
          "hemiDirection",
          "hemiIntensity",
          "cameraPosition",
          "time",
          "metallic",
          "roughness",
        ],
        samplers: ["albedoTexture", "metallicRoughnessTexture", "bumpTexture"],
      }
    );

    shaderMaterial.setTexture("albedoTexture", heartMesh.material.albedoTexture);
    shaderMaterial.setTexture("metallicRoughnessTexture", heartMesh.material.metallicTexture);
    shaderMaterial.setTexture("bumpTexture", heartMesh.material.bumpTexture);

    shaderMaterial.setFloat("metallic", 0.07);
    shaderMaterial.setFloat("roughness", 0.18);

    dirLight.direction = new BABYLON.Vector3(0.17, -0.35, -0.91);

    scene.registerBeforeRender(() => {
      shaderMaterial.setFloat("time", performance.now() * 0.00075);
      shaderMaterial.setVector3("cameraPosition", scene.activeCamera.position);
      shaderMaterial.setVector3("lightPosition", dirLight.position);
      shaderMaterial.setVector3("lightDirection", dirLight.direction);
      shaderMaterial.setVector3("hemiDirection", hemiLight.direction);
      shaderMaterial.setFloat("hemiIntensity", hemiLight.intensity);
    });

    shaderMaterial.addUniformsToInspector([
      {
        label: "Metallic",
        propertyName: "metallic",
        type: BABYLON.InspectableType.Slider,
        min: 0.0,
        max: 1.0,
        step: 0.01,
      },
      {
        label: "Roughness",
        propertyName: "roughness",
        type: BABYLON.InspectableType.Slider,
        min: 0.0,
        max: 1.0,
        step: 0.01,
      },
    ]);

    heartMesh.material = shaderMaterial;

    heartMesh.inspectableCustomProperties = camera.inspectableCustomProperties || [];
    heartMesh.inspectableCustomProperties.push({
      label: "Original PBRMaterial",
      type: BABYLON.InspectableType.Button,
      callback() {
        if (isPBR) {
          heartMesh.material = originalMaterial;
          hemiLight.intensity = 1;
        } else {
          heartMesh.material = shaderMaterial;
          hemiLight.intensity = hemiIntensity;
        }

        isPBR = !isPBR;
      },
    });

    var advancedTexture = BABYLON.GUI.AdvancedDynamicTexture.CreateFullscreenUI("UI");

    var panel = new BABYLON.GUI.StackPanel();
    panel.width = "200px";
    panel.isVertical = false;
    panel.horizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_RIGHT;
    panel.verticalAlignment = BABYLON.GUI.Control.VERTICAL_ALIGNMENT_CENTER;
    advancedTexture.addControl(panel);

    var checkbox = new BABYLON.GUI.Checkbox();
    checkbox.width = "20px";
    checkbox.height = "20px";
    checkbox.isChecked = isPBR;
    checkbox.color = "green";
    checkbox.onIsCheckedChangedObservable.add(function (value) {
      isPBR = !isPBR;

      if (isPBR) {
        heartMesh.material = shaderMaterial;
        hemiLight.intensity = hemiIntensity;
        header.text = " Use ShaderMaterial";
      } else {
        heartMesh.material = originalMaterial;
        hemiLight.intensity = 1;
        header.text = " Use PBRMaterial";
      }
    });
    panel.addControl(checkbox);

    var header = new BABYLON.GUI.TextBlock();
    header.text = " Use ShaderMaterial";
    header.width = "180px";
    header.marginLeft = "5px";
    header.textHorizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_LEFT;
    header.color = "white";
    panel.addControl(header);
  });

  BABYLON.ShaderMaterial.prototype.addUniformsToInspector = function (inspectableCustomProperties) {
    if (this.inspectableCustomProperties) {
      this.inspectableCustomProperties.push(...inspectableCustomProperties);
    } else {
      this.inspectableCustomProperties = inspectableCustomProperties;
    }

    const setValue = (property, value) => {
      switch (property.type) {
        case BABYLON.InspectableType.Vector2:
          this.setVector2(property.propertyName, value);
          break;
        case BABYLON.InspectableType.Vector3:
          this.setVector3(property.propertyName, value);
          break;
        case BABYLON.InspectableType.Quaternion:
          this.setQuaternion(property.propertyName, value);
          break;
        case BABYLON.InspectableType.Color3:
          this.setColor3(property.propertyName, value);
          break;
        case BABYLON.InspectableType.Slider:
          this.setFloat(property.propertyName, value);
          break;
        case BABYLON.InspectableType.Checkbox:
          this.setInt(property.propertyName, value ? 1 : 0);
          break;
        default:
          break;
      }
    };

    const getValue = (property) => {
      switch (property.type) {
        case BABYLON.InspectableType.Vector2:
          return this._vectors2[property.propertyName];
        case BABYLON.InspectableType.Vector3:
          return this._vectors3[property.propertyName];
        case BABYLON.InspectableType.Quaternion:
          return this._quaternions[property.propertyName];
        case BABYLON.InspectableType.Color3:
          return this._colors3[property.propertyName];
        case BABYLON.InspectableType.Slider:
          return this._floats[property.propertyName];
        case BABYLON.InspectableType.Checkbox:
          return this._ints[property.propertyName] === 1;
        default:
          return undefined;
      }
    };

    inspectableCustomProperties.forEach((property) => {
      Object.defineProperty(this, property.propertyName, {
        set: (value) => setValue(property, value),
        get: () => getValue(property),
        enumerable: true,
        configurable: true,
      });
    });
  };

  let azimuth = 169;
  let elevation = 339;

  const updateLightDirection = (azimuthValue, elevationValue) => {
    if (dirLight) {
      const azimuthRad = BABYLON.Tools.ToRadians(azimuthValue);
      const elevationRad = BABYLON.Tools.ToRadians(elevationValue);

      const x = Math.cos(elevationRad) * Math.sin(azimuthRad);
      const y = Math.sin(elevationRad);
      const z = Math.cos(elevationRad) * Math.cos(azimuthRad);

      dirLight.direction = new BABYLON.Vector3(x, y, z).normalize();
    }
  };

  updateLightDirection(azimuth, elevation);

  const plane = BABYLON.MeshBuilder.CreatePlane("plane", { size: 2 }, scene);
  plane.rotation.y = Math.PI;

  BABYLON.Effect.ShadersStore["heartbeatVertexShader"] = `
      precision highp float;
      attribute vec3 position;
      attribute vec2 uv;
      varying vec2 vUV;

      void main() {
          vUV = uv;
          gl_Position = vec4(position, 1.0);
      }
  `;

  BABYLON.Effect.ShadersStore["heartbeatFragmentShader"] = `
      precision highp float;

      varying vec2 vUV;

      uniform vec2 iResolution;
      uniform float iTime;

      #define AA_FALLOFF 1.2
      #define GRID_WIDTH 0.1
      #define CURVE_WIDTH 10.0
      #define FUNC_SAMPLE_STEP 0.08
      #define SCOPE_RATE 0.5

      float pp;

      float sinc(float x) {
          return (x == 0.0) ? 1.0 : sin(x) / x;
      }

      float triIsolate(float x) {
          return abs(-1.0 + fract(clamp(x, -0.5, 0.5)) * 2.0);
      }

      float heartbeat(float x) {
          float prebeat = -sinc((x - 0.4) * 40.0) * 0.6 * triIsolate((x - 0.4) * 1.0);
          float mainbeat = (sinc((x - 0.5) * 60.0)) * 1.2 * triIsolate((x - 0.5) * 0.7);
          float postbeat = sinc((x - 0.85) * 15.0) * 0.5 * triIsolate((x - 0.85) * 0.6);
          return (prebeat + mainbeat + postbeat) * triIsolate((x - 0.625) * 0.8);
      }

      float func(float x) {
          return 0.5 * heartbeat(mod((x - iTime * 0.5), 1.3));
      }

      void main() {
          vec2 uv = vUV;

          float aspect = iResolution.x / iResolution.y;
          float graphRange = 0.4 + pow(1.2, sin(iTime * 0.6) * 1.2);
          vec2 graphSize = vec2(aspect * graphRange, graphRange);
          vec2 xy = (uv - 0.5) * graphSize;

          pp = graphSize.y / iResolution.y;

          // Pulse 페이딩 효과 추가
          float rate = SCOPE_RATE;
          float pulse = fract(iTime * rate) * 4.0 - 1.5;
          float fade = pulse - xy.x;
          if (fade < 0.0) fade += 10.0;
          fade *= 0.25;
          fade = clamp(fade / rate, 0.0, 1.0);
          fade = 1.0 - fade;
          fade = fade * fade * fade;
          fade *= step(-1.5, xy.x) * step(xy.x, 2.5);

          float y = func(xy.x);
          float dist = abs(xy.y - y);
          float line = smoothstep(0.02, 0.01, dist);

          vec4 baseCol = vec4(0.0, 1.0, 0.7, fade * line);

          if (line == 0.0) {
              baseCol.a = 0.0;
          }

          gl_FragColor = baseCol;
      }
  `;

  const ecgPulseShaderMaterial = new BABYLON.ShaderMaterial(
    "shader",
    scene,
    {
      vertex: "heartbeat",
      fragment: "heartbeat",
    },
    {
      attributes: ["position", "uv"],
      uniforms: ["iResolution", "iTime"],
      needAlphaBlending: true,
    }
  );

  ecgPulseShaderMaterial.setVector2("iResolution", new BABYLON.Vector2(engine.getRenderWidth(), engine.getRenderHeight()));
  ecgPulseShaderMaterial.setFloat("iTime", 0);
  ecgPulseShaderMaterial.backFaceCulling = false;
  ecgPulseShaderMaterial.transparencyMode = BABYLON.Material.MATERIAL_ALPHABLEND;
  ecgPulseShaderMaterial.alphaMode = BABYLON.Engine.ALPHA_COMBINE;

  plane.material = ecgPulseShaderMaterial;

  const defaultMaterial = new BABYLON.StandardMaterial("default", scene);
  defaultMaterial.alpha = 0;

  scene.onBeforeRenderObservable.add(() => {
    if (isPBR) {
      plane.material = ecgPulseShaderMaterial;
      ecgPulseShaderMaterial.setFloat("iTime", performance.now() / 1500);
    } else {
      plane.material = defaultMaterial;
      ecgPulseShaderMaterial.setFloat("iTime", 0);
    }
  });

  return scene;
}
